"""E0: fit quotes generated by a known model and compare with the truth.

Run with `uv run python experiments/e0_synthetic.py`. Writes results/e0_synthetic/.
"""

import time
from pathlib import Path

import numpy as np

from sanos.checks import arbitrage_violations
from sanos.fit import fit
from sanos.report import git_commit, metrics_table, plot_expiry
from sanos.synthetic import mixture_density, mixture_quotes

OUT = Path(__file__).parent.parent / "results" / "e0_synthetic"

# The generating model: a mixture of two Black-Scholes models.
WEIGHTS, VOLS = (0.6, 0.4), (0.3, 0.8)
EXPIRIES = [0.25, 0.5, 1.0]
STRIKES = np.linspace(0.6, 1.6, 21)
HALF_SPREAD = 1e-4

# label -> (eta, largest gap between model strikes). The linear model lives on the
# quoted strikes only, which is the linear interpolation of section 2.2.
SETTINGS = {
    "linear (η = 0)": (0.0, np.inf),
    "η = 0.06": (0.06, 0.02),
    "η = 0.25": (0.25, 0.02),
}
# The arbitrage checks look beyond the quoted strikes and between the expiries.
CHECK_EXPIRIES = [0.1, 0.25, 0.4, 0.5, 0.75, 1.0]
CHECK_STRIKES = np.linspace(0.02, 5.0, 800)


def main() -> None:
    commit = git_commit()  # before anything is written
    OUT.mkdir(parents=True, exist_ok=True)
    quotes = mixture_quotes(EXPIRIES, STRIKES, WEIGHTS, VOLS, HALF_SPREAD)

    surfaces, summary = {}, []
    for label, (eta, max_gap) in SETTINGS.items():
        start = time.perf_counter()
        surfaces[label] = fit(quotes, eta=eta, max_gap=max_gap)
        seconds = time.perf_counter() - start
        violations = arbitrage_violations(
            surfaces[label].call, CHECK_EXPIRIES, CHECK_STRIKES
        )
        summary += [
            f"## {label}",
            f"Fitted in {1000 * seconds:.0f} ms. Largest model strike gap: {max_gap}.",
            metrics_table(quotes, surfaces[label]),
            "Largest arbitrage violations on the check grid: "
            + ", ".join(f"{name} {v:.0e}" for name, v in violations.items())
            + ".",
        ]

    for q in quotes:
        figure = plot_expiry(
            q, surfaces, lambda k, q=q: mixture_density(k, q.expiry, WEIGHTS, VOLS)
        )
        figure.savefig(OUT / f"expiry_{q.expiry:.2f}.png", dpi=150)

    header = [
        "# E0: synthetic quotes from a known model",
        f"Produced by `experiments/e0_synthetic.py` at commit `{commit}`.",
        f"Model: mixture of Black-Scholes, weights {WEIGHTS}, volatilities {VOLS}. "
        f"Quotes: expiries {EXPIRIES}, {len(STRIKES)} strikes from {STRIKES[0]} to "
        f"{STRIKES[-1]}, mid = model price, half-spread {HALF_SPREAD}.",
        "Errors are in half-spreads. A miss is a model price outside bid/ask; its size "
        "is the distance to the nearer of bid and ask.",
    ]
    (OUT / "README.md").write_text("\n\n".join(header + summary) + "\n")


if __name__ == "__main__":
    main()
